                               'seasonal_adjustment':d['labels']['ADJUSTMENT'],'breaks_inside_window_withheld':True,
                               'columns':['chart_anchor','prior_period','current_source_row','prior_source_row','current_index','prior_index','growth_percent','rejection'],
